int main(){try{auto common=std::make_shared<CommonCatalog>();common->extended_skills=true;common->actor_ids={"speaker","listener"};common->places.insert("home",{"home","town",{}});common->items.insert("food",{"food",1,1,false,false});RoleDefinition role;role.id="birth_talk";role.place_id="home";role.initial_actor="speaker";common->roles.insert(role.id,role);CommonState initial;initial.identity.world_id[0]=4;initial.identity.execution_epoch=8;initial.identity.revision=6;initial.identity.tick=20;initial.metadata.player_actor_id="listener";initial.metadata.scenario_id="birth-source";initial.next_instance_id=100;initial.roles.insert(role.id,{"speaker",true,{}});for(const auto* id:{"speaker","listener"}){ActorRecord actor;actor.id=id;actor.alive=true;actor.available=true;actor.hp=100;actor.birth_tick=20-18*720;actor.location=SettlementLocation{"town","home"};actor.inventory_id=StableId{"bag:"}+id;initial.actors.insert(id,actor);initial.inventories.insert(actor.inventory_id,{actor.inventory_id,{Owner::Kind::actor,id,{}},20,0,{},{}});}CommonStore c(initial,common);
    InteractionCatalog interactions;interactions.common=common;DialogueDefinition dialogue;dialogue.id="birth_dialogue";dialogue.context_role=role.id;dialogue.entry="arrangement";DialogueNode node;node.id="arrangement";node.kind="say";dialogue.nodes.push_back(node);node.id="marriage_only";dialogue.nodes.push_back(node);interactions.dialogues.push_back(dialogue);InteractionState meeting;InteractionSession session;session.id="interaction:5";session.actor_id="listener";session.dialogue_id=dialogue.id;session.node_id="arrangement";session.phase="say";session.context={"home","speaker",role.id};meeting.interactions.push_back(session);InteractionAccess access;access.battle_occupied=[](const StableId&){return false;};access.resolve_location=[&](const StableId& id){return c.actor(id)->location;};access.role=[&](const StableId& id)->std::optional<RoleAssignmentView>{const auto* value=c.state().roles.find(id);return value?std::optional<RoleAssignmentView>{{value->actor_id,value->enabled}}:std::nullopt;};FamilyCatalog family;family.enabled=true;family.extended_skills=true;IdentityPrototype baby;baby.skills.extended=ActorExtendedSkills{};family.prototypes.insert("baby",baby);BirthArrangementCatalog catalog;catalog.enabled=true;BirthArrangementDefinition definition;definition.id="arrangement";definition.speaker_actor_id="speaker";definition.listener_actor_id="listener";definition.dialogue_id=dialogue.id;definition.node_id="arrangement";definition.terms={"speaker","listener","listener","home","bag:listener","food","baby",540,2,1,30,{}};catalog.arrangements.insert(definition.id,definition);auto before=encode_common_state(c.state());check(validate_birth_arrangement_catalog(catalog,*common,interactions,family).ok,"explicit personal care terms rejected");auto quote=preview_birth_arrangement_source(c,meeting,interactions,access,family,catalog,"listener","arrangement");check(quote.ok&&revalidate_birth_arrangement_source(c,meeting,interactions,access,family,catalog,quote.value).ok,"actual adult birth node rejected");check(compare_boundary(before,encode_common_state(c.state())).exact(),"intent source created child or reserved food");check(c.state().inventories.find("bag:listener")->lots.empty(),"source assumed food already supplied");
    auto changed=catalog;changed.arrangements.find("arrangement")->terms.caregiver_actor_id="unconsenting_third_person";check(!validate_birth_arrangement_catalog(changed,*common,interactions,family).ok,"third person assigned free childcare");changed=catalog;changed.arrangements.find("arrangement")->terms.payer_actor_id="speaker";check(!validate_birth_arrangement_catalog(changed,*common,interactions,family).ok,"player spent NPC private inventory");changed=catalog;changed.arrangements.find("arrangement")->terms.birth_duration_ticks=0;check(!validate_birth_arrangement_catalog(changed,*common,interactions,family).ok,"instant birth promise accepted");auto gifted=family;gifted.prototypes.find("baby")->skills.extended->medicine=50;check(!validate_birth_arrangement_catalog(catalog,*common,interactions,gifted).ok,"newborn inherited learned medicine");check(!preview_birth_arrangement_source(c,meeting,interactions,access,family,catalog,"speaker","arrangement").ok,"listener decision forged by other actor");meeting.interactions.front().node_id="marriage_only";check(!preview_birth_arrangement_source(c,meeting,interactions,access,family,catalog,"listener","arrangement").ok,"marriage node granted birth consent");meeting.interactions.front().node_id="arrangement";c.state().actors.find("speaker")->birth_tick=21-18*720;check(!preview_birth_arrangement_source(c,meeting,interactions,access,family,catalog,"listener","arrangement").ok,"minor birth consent admitted");c.state().actors.find("speaker")->birth_tick=20-18*720;c.state().inventories.find("bag:listener")->owner={Owner::Kind::organization,"public",{}};check(!preview_birth_arrangement_source(c,meeting,interactions,access,family,catalog,"listener","arrangement").ok,"public food pledge treated as own");c.state().inventories.find("bag:listener")->owner={Owner::Kind::actor,"listener",{}};
    auto json=encode_birth_arrangement_source(quote.value.source);auto decoded=decode_birth_arrangement_source(json);check(decoded.ok&&validate_birth_arrangement_source(c,interactions,family,catalog,decoded.value).ok,"birth source JSON cold");auto altered=json;altered.find("terms")->as<BoundaryValue::Dict>()->emplace_back("food_per_period",BoundaryValue{Integer{10000}});check(!decode_birth_arrangement_source(altered).ok,"nested repeated food terms admitted");altered=json;altered.find("context")->as<BoundaryValue::Dict>()->emplace_back("provider_actor_id",BoundaryValue{"listener"});check(!decode_birth_arrangement_source(altered).ok,"duplicate context provider admitted");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_birth_arrangement_source(writer,decoded.value).ok&&writer.finish().ok,"typed birth source write");const auto& input=bytes;CodecVisitor reader(input);BirthArrangementSource cold;check(visit_birth_arrangement_source(reader,cold).ok&&reader.finish().ok&&compare_boundary(json,encode_birth_arrangement_source(cold)).exact(),"typed birth source exact cold");cold.terms.food_per_period=2;check(!validate_birth_arrangement_source(c,interactions,family,catalog,cold).ok,"altered food responsibility admitted");cold=decoded.value;c.state().identity.tick=30;c.state().identity.execution_epoch=9;c.state().actors.find("speaker")->alive=false;c.state().actors.find("speaker")->available=false;check(validate_birth_arrangement_source(c,interactions,family,catalog,cold).ok,"later death erased previous statement");check(!revalidate_birth_arrangement_source(c,meeting,interactions,access,family,catalog,quote.value).ok,"past deceased consent authorizes new plan");std::cout<<"BIRTH_ARRANGEMENT_SOURCE "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<"BIRTH_ARRANGEMENT_SOURCE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
